    def minOperations(self, boxes):
        """
        :type boxes: str
        :rtype: List[int]
        """
        n = len(boxes)
        ans = [0 for _ in range(n)]
        for i in range(n):
            if boxes[i] == '0':
                continue
            for j in range(n):
                ans[j] += abs(i - j)
        return ans
